CREATE MATERIALIZED VIEW non_leaf_959 AS
SELECT pi.id AS pi_id, pi.person_id AS pi_person_id, pi.info_type_id AS pi_info_type_id, pi.info AS pi_info, pi.note AS pi_note, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role, t.id AS t_id, t.title AS t_title, t.imdb_index AS t_imdb_index, t.kind_id AS t_kind_id, t.production_year AS t_production_year, t.imdb_id AS t_imdb_id, t.phonetic_code AS t_phonetic_code, t.episode_of_id AS t_episode_of_id, t.season_nr AS t_season_nr, t.episode_nr AS t_episode_nr, t.series_years AS t_series_years, t.md5sum AS t_md5sum, mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, it1.id AS it1_id, it1.info AS it1_info, kt.id AS kt_id, kt.kind AS kt_kind
FROM person_info AS pi, cast_info AS ci, role_type AS rt, title AS t, movie_info AS mi1, info_type AS it1, kind_type AS kt
WHERE pi.person_id = ci.person_id AND pi.info_type_id = 24 AND ci.movie_id = t.id AND ci.role_id = rt.id AND rt.role IN ('cinematographer', 'composer', 'editor', 'writer') AND t.id = mi1.movie_id AND t.production_year <= 2015 AND t.production_year >= 1925 AND mi1.info_type_id = it1.id AND mi1.info IN ('70 mm 6-Track', 'Brazil:16', 'Canada:PA', 'Canada:R', 'Finland:(Banned)', 'Germany:o.Al.', 'Iceland:L', 'Ireland:12A', 'Ireland:PG', 'Italy:VM14', 'New Zealand:PG', 'Peru:18', 'Philippines:G', 'Philippines:R-13', 'Portugal:M/16', 'Singapore:PG13', 'South Korea:12', 'Spain:7') AND it1.id IN ('2', '5', '6}'::integ') AND kt.id = t.kind_id AND kt.kind IN ('episode', 'movie', 'tv series');